import{_ as i,o as a,c as e,a4 as r}from"./chunks/framework.BRzJ4ijD.js";const g=JSON.parse('{"title":"复制 (Replication)","description":"","frontmatter":{},"headers":[],"relativePath":"distributed/replication/index.md","filePath":"distributed/replication/README.md","lastUpdated":1788475713000}'),o={name:"distributed/replication/index.md"};function l(s,t,n,p,d,c){return a(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="复制-replication" tabindex="-1">复制 (Replication) <a class="header-anchor" href="#复制-replication" aria-label="Permalink to &quot;复制 (Replication)&quot;">​</a></h1><p>复制是分布式系统的&quot;心脏&quot;——把一份数据放 N 副本, 让 N 节点都持有&quot;看似同一份数据&quot;。复制的三大 axis:</p><ol><li><strong>拓扑</strong>: 单主 (primary-backup, leader-follower) / 多主 (multi-master) / 无主 (leaderless)</li><li><strong>持久性 vs 可用性</strong>: N、同步 vs 异步、quorum 大小</li><li><strong>冲突解决</strong>: 更新顺序、last-writer-wins、向量时钟 + merge、CRDT</li></ol><p>工业实现:</p><ul><li><p><strong>单主</strong> = MySQL replication、PostgreSQL streaming replica、Kafka partition、etcd raft。</p></li><li><p><strong>多主</strong> = CouchDB、DynamoDB Global Table、Cassandra multi-DC、MySQL grouping row。</p></li><li><p><strong>无主</strong> = Dynamo,Cassandra, Riak, Voldemort(Sticky optional LWW)。</p></li><li><p><strong>CRDT</strong> = Riak (counters, sets), Redis (CRDT data types), Automerge, Yjs 文档协同。</p></li><li><p><a href="./topologies">主从 / 多主 / 无主复制</a></p></li><li><p><a href="./crdt">CRDT：无冲突数据类型</a></p></li><li><p><a href="./repair">读修复 / 反熵 / hinted handoff</a></p></li></ul>',5)])])}const m=i(o,[["render",l]]);export{g as __pageData,m as default};
